mapper.select:
SELECT COUNT(*)
FROM offline_package_manifest
WHERE id = #{manifestId}

SELECT COUNT(*)
FROM offline_package_manifest
WHERE incident_id = #{incidentId}
  AND manifest_hash <> #{purgedManifestHash}

mapper.delete:
DELETE FROM offline_package_installation
WHERE offline_package_manifest_id = #{manifestId}
  AND police_phone_id = #{policePhoneId}

mapper.select:
SELECT COUNT(*)
FROM offline_package_installation
WHERE id = #{id}

SELECT i.id, m.incident_id, i.police_phone_id, i.status, i.version, 901 AS sequence_number, m.manifest_version, #{activeManifestVersion} AS active_manifest_version, i.status = 'READY' AS ready_for_offline_use FROM offline_package_installation i JOIN offline_package_manifest m ON m.id = i.offline_package_manifest_id WHERE i.id IN
#{id}
ORDER BY i.police_phone_id

mapper.update:
UPDATE offline_package_manifest
SET
    manifest_hash = #{purgedManifestHash},
    manifest_payload = '{"purged":true,"reason":"package_purged","packageItems":[]}',
    updated_at = #{updatedAt}
WHERE incident_id = #{incidentId}
  AND manifest_hash <> #{purgedManifestHash}
